- Inside the character-check loop you compared with `charpar[i]` instead of `charpar[c]`.
- Use primitive `boolean[]` (initially false) and print results.

Below is a corrected version of `Java/src/ejercicios/sopadeletras.java`. It keeps your logic (searching up/down/left/right) and prints "YES"/"NO" for each word.

```java
// java
package ejercicios;

import java.util.Scanner;

public class sopadeletras {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int y = sc.nextInt();
        int x = sc.nextInt();

        char[][] matriu = JCllenarmatriz(y, x, sc);
        int nparaules = sc.nextInt();
        String[] par = JCllenarmatriz2(nparaules, sc);
        boolean[] bollist = new boolean[nparaules]; // defaults to false

        for (int i = 0; i < nparaules; i++) {
            char[] charpar = par[i].toCharArray();

            for (int h = 0; h < matriu.length; h++) {
                for (int j = 0; j < matriu[h].length; j++) { // fixed index here
                    if (matriu[h][j] == charpar[0]) {
                        int contadorarr = 1;
                        int contadorab = 1;
                        int contadord = 1;
                        int contadori = 1;

                        for (int c = 1; c < charpar.length; c++) {
                            if (esticDins(h + c, j, matriu)) {
                                if (matriu[h + c][j] == charpar[c]) { // use c not i
                                    contadorab++;
                                }
                            }
                            if (esticDins(h - c, j, matriu)) {
                                if (matriu[h - c][j] == charpar[c]) {
                                    contadorarr++;
                                }
                            }
                            if (esticDins(h, j + c, matriu)) {
                                if (matriu[h][j + c] == charpar[c]) {
                                    contadord++;
                                }
                            }
                            if (esticDins(h, j - c, matriu)) {
                                if (matriu[h][j - c] == charpar[c]) {
                                    contadori++;
                                }
                            }
                        }

                        if (contadorab == charpar.length || contadorarr == charpar.length
                                || contadord == charpar.length || contadori == charpar.length) {
                            bollist[i] = true;
                        }
                    }
                }
            }
        }

        // Print results (one line per word)
        for (int i = 0; i < nparaules; i++) {
            System.out.println(bollist[i] ? "YES" : "NO");
        }

        sc.close();
    }

    public static char[][] JCllenarmatriz(int filas, int cols, Scanner sc) {
        char[][] matriu = new char[filas][cols];
        for (int i = 0; i < filas; i++) {
            String linea = sc.next();
            for (int w = 0; w < cols; w++) {
                matriu[i][w] = linea.charAt(w);
            }
        }
        return matriu;
    }

    public static String[] JCllenarmatriz2(int cols, Scanner sc) {
        String[] matriu = new String[cols];
        for (int i = 0; i < cols; i++) {
            matriu[i] = sc.next();
        }
        return matriu;
    }

    public static boolean esticDins(int f, int c, char[][] matriu) {
        return f >= 0 && f < matriu.length && c >= 0 && c < matriu[f].length;
    }
}
