Problems:
- Logic inverted: a row with no zeros is a *full* row, but the code reset `count` on full rows instead of incrementing it.
- Uses `matriu[0].length` for every row; should use `matriu[i].length`.
- The code returned the final `count` only; better track the maximum consecutive full rows and print that or `TETRIS` when >= 4.
- Unused `esticDins` with wrong signature — removed.

Fixed `Java/src/ejercicios/Tetris.java`: it counts consecutive full rows, tracks the maximum, and prints `TETRIS` if any sequence >= 4, otherwise prints the maximum.

```java
// java
package ejercicios;

import java.util.Scanner;

public class Tetris {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int y = sc.nextInt();
        int x = sc.nextInt();

        int[][] matriu = JCllenarmatriz(y, x, sc);
        sc.close();

        int current = 0;
        int maxConsecutiveFull = 0;
        for (int i = 0; i < matriu.length; i++) {
            boolean full = true;
            for (int w = 0; w < matriu[i].length; w++) {
                if (matriu[i][w] == 0) {
                    full = false;
                    break;
                }
            }
            if (full) {
                current++;
                if (current > maxConsecutiveFull) maxConsecutiveFull = current;
            } else {
                current = 0;
            }
        }

        if (maxConsecutiveFull >= 4) {
            System.out.println("TETRIS");
        } else {
            System.out.println(maxConsecutiveFull);
        }
    }

    public static int[][] JCllenarmatriz(int filas, int cols, Scanner sc) {
        int[][] matriu = new int[filas][cols];
        for (int i = 0; i < matriu.length; i++) {
            for (int w = 0; w < matriu[i].length; w++) {
                matriu[i][w] = sc.nextInt();
            }
        }
        return matriu;
    }
}
